using Challenge;void C(string id,Func<bool> f){try{Console.WriteLine($"{id}|{(f()?"pass":"fail")}");}catch{Console.WriteLine($"{id}|fail");}}string Root()=>Path.Combine(Path.GetTempPath(),"up-"+Guid.NewGuid());C("C01",()=>{var root=Root();var r=Uploads.Save(root,"../evil.pdf","application/pdf",new MemoryStream("%PDF-x"u8.ToArray()),20);return r.Path is not null&&Path.GetFullPath(r.Path).StartsWith(Path.GetFullPath(root));});C("C02",()=>{var root=Root();var r=Uploads.Save(root,"x.pdf","application/pdf",new MemoryStream(new byte[100]),10);return !r.Accepted&&(!Directory.Exists(root)||!Directory.EnumerateFiles(root).Any());});C("C03",()=>!Uploads.Save(Root(),"x.pdf","application/pdf",new MemoryStream("hello"u8.ToArray()),20).Accepted);C("C04",()=>{var root=Root();var a=Uploads.Save(root,"x.pdf","application/pdf",new MemoryStream("%PDF-a"u8.ToArray()),20);var b=Uploads.Save(root,"x.pdf","application/pdf",new MemoryStream("%PDF-b"u8.ToArray()),20);return a.Path!=b.Path;});C("C05",()=>{var root=Root();Uploads.Save(root,"x","x",new MemoryStream(new byte[30]),10);return !Directory.EnumerateFiles(root).Any();});
